      }
    ],
    "h_statements": [
      {
        "code": "H335",
        "text": "호흡기계 자극을 일으킬 수 있음",
        "line": "p1:L26"
      },
      {
        "code": "H350",
        "text": "암을 일으킬 수 있음",
        "line": "p1:L27"
      },
      {
        "code": "H360",
        "text": "태아 또는 생식능력에 손상을 일으킬 수 있음",
        "line": "p1:L28"
      },
      {
        "code": "H362",
        "text": "모유를 먹는 아이에게 유해할 수 있음",
        "line": "p1:L29"
      },
      {
        "code": "H372",
        "text": "장기간 또는 반복노출 되면 신체에 손상을 일으킴",
        "line": "p1:L30"
      },
      {
        "code": "H413",
        "text": "장기적인 영향에 의해 수생생물에 유해의 우려가 있음",
        "line": "p1:L31"
      }
    ],
    "p_statements": [
      {
        "code": "P201",
        "type": "예방",
        "text": "사용 전 취급 설명서를 확보하시오.",
        "line": "p1:L33"
      },
      {
        "code": "P202",
        "type": "예방",
        "text": "모든 안전 예방조치 문구를 읽고 이해하기 전에는 취급하지 마시오.",
        "line": "p2:L1"
      },
      {
        "code": "P260",
        "type": "예방",
        "text": "(분진·흄·가스·미스트·증기·스프레이)를(을) 흡입하지 마시오.",
        "line": "p2:L2"
      },
      {
        "code": "P261",
        "type": "예방",
        "text": "(분진·흄·가스·미스트·증기·스프레이)의 흡입을 피하시오.",
        "line": "p2:L3"
      },
      {
        "code": "P263",
        "type": "예방",
        "text": "임신 및 수유 기간에는 접촉하지 마시오.",
        "line": "p2:L4"
      },
      {
        "code": "P264",
        "type": "예방",
        "text": "취급 후에는 취급 부위를 철저히 씻으시오.",
        "line": "p2:L5"
      },
      {
        "code": "P270",
        "type": "예방",
        "text": "이 제품을 사용할 때에는 먹거나, 마시거나 흡연하지 마시오.",
        "line": "p2:L6"
      },
      {
        "code": "P271",
        "type": "예방",
        "text": "옥외 또는 환기가 잘 되는 곳에서만 취급하시오.",
        "line": "p2:L7"
      },
      {
        "code": "P273",
        "type": "예방",
        "text": "환경으로 배출하지 마시오.",
        "line": "p2:L8"
      },
      {
        "code": "P280",
        "type": "예방",
        "text": "(보호장갑·보호의·보안경·안면보호구)를(을) 착용하시오.",
        "line": "p2:L9"
      },
      {
        "code": "P304+P340",
        "type": "대응",
        "text": "흡입하면 신선한 공기가 있는 곳으로 옮기고 호흡하기 쉬운 자세로 안정을 취하시오.",
        "line": "p2:L11"
      },
      {
        "code": "P308+P313",
        "type": "대응",
        "text": "노출되거나 노출이 우려되면 의학적인 조치·조언을 구하시오.",
        "line": "p2:L12"
      },
      {
        "code": "P312",
        "type": "대응",
        "text": "불편함을 느끼면 의료기관의 진찰을 받으시오.",
        "line": "p2:L13"
      },
      {
        "code": "P314",
        "type": "대응",
        "text": "불편함을 느끼면 의학적인 조치·조언을 구하시오.",
        "line": "p2:L14"
      },
      {
        "code": "P403+P233",
        "type": "저장",
        "text": "환기가 잘 되는 곳에 보관하시오.용기를 단단히 밀폐하시오.",
        "line": "p2:L16"
      },
      {
        "code": "P405",
        "type": "저장",
        "text": "잠금장치가 있는 저장장소에 저장하시오.",
        "line": "p2:L17"
      },
      {
        "code": "P501",
        "type": "폐기",
        "text": "(관련 법규에 명시된 내용에 따라) 내용물 용기를 폐기하시오.",
        "line": "p2:L19"
      }
    ],
